function finishTime(skill: number[], mana: number[]): number {
  const n = skill.length;
  const done = new Array(n).fill(0);
  for (const x of mana) {
    let t = done[0];
    let clash = true;
    while (clash) {
      clash = false;
      let at = t;
      for (let i = 0; i < n; i++) {
        if (at < done[i]) { t += done[i] - at; clash = true; break; }
        at += skill[i] * x;
      }
    }
    let at = t;
    for (let i = 0; i < n; i++) { at += skill[i] * x; done[i] = at; }
  }
  return done[n - 1];
}

