function finishTime(skill: number[], mana: number[]): number {
  const n = skill.length;
  const pre = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + skill[i];
  const done = new Array(n).fill(0);
  for (const x of mana) {
    let t = 0;
    for (let i = 0; i < n; i++) t = Math.max(t, done[i] - pre[i] * x);
    for (let i = 0; i < n; i++) done[i] = t + pre[i + 1] * x;
  }
  return done[n - 1];
}

