        n = len(skill)
        pre = [0] * (n + 1)
        for i, s in enumerate(skill):
            pre[i + 1] = pre[i] + s
        done = [0] * n
        for x in mana:
            t = max(done[i] - pre[i] * x for i in range(n))
            t = max(t, 0)
            for i in range(n):
                done[i] = t + pre[i + 1] * x
        return done[-1]

